// ── Helpers ───────────────────────────────────────────────────
function nodeRadius(degree: number): number {
  return Math.max(8, Math.min(28, 8 + Math.sqrt(Math.max(0, degree)) * 4.2));
}

function statusColor(node: CanvasNode): string {
  if (node.lane === 'facet')    return LANE_COLOR.facet;
