```typescript
function compactError(raw: string | undefined): string {
  if (!raw) return '';
  try {
    const parsed = JSON.parse(raw) as { title?, detail?, code? };
    const message = parsed.detail || parsed.title || parsed.code || '';
    return message.includes('does not expose command path "pm-graph"') ? '' : message;
  } catch {
    const message = raw.replace(/\s+/g, ' ').trim();
    return message.includes('does not expose command path "pm-graph"') ? '' : message;
  }
}
```
Docstring: "Extracts a short user-facing error message from a raw error string (JSON detail/title/code, or the trimmed raw text), returning an empty string when the error is just the missing pm-graph extension."

