function directNeighborIds(nodeId: string, rels: GraphRelationship[]): Set<string> {
  const ids = new Set<string>([nodeId]);
  for (const r of rels) {
    if (r.from === nodeId) ids.add(r.to);
    if (r.to   === nodeId) ids.add(r.from);
  }
  return ids;
}
